    pins={'preflight.py': 'de463a599acc2b5a43676c0ab5e957505f4ecee012662835c0733e4413781b10', 'reboot-reviewed.py': '303c110ea2ff3fa081f53818a27d20238b2621b3b00f444f0b8d5817ab2d87d7', 'recover-release-reviewed.py': '0e3938d06d6bcbfa9eab0249479bab5e54fe5162a3669a3026a39a0d204c4f44', 'remaining-backup-and-actor-readonly.py': 'e102a5a4cea06b5509d3b7428adab13b3bf942ac7185ad8d240f7a2372257bb6', 'preparation-readonly.py': '7542950280843c0034a4f7b1a9ce717d6632cddb9bc6f6a562ce77b03c2c51b4'}
    require(set(payloads)==set(pins),'PACKAGE_SCOPE')
    for name,body in payloads.items():require(hashlib.sha256(body).hexdigest()==pins[name],'PACKAGE_MEMBER_CHANGED')
    def memory_module(name,body):
     m=types.ModuleType(name);m.__file__='/var/lib/passvero-reboot-recovery-20261019/'+name+'.py'
     exec(compile(body,m.__file__,'exec'),m.__dict__);return m
    h=memory_module('reboot_reviewed',payloads['reboot-reviewed.py'])
