    scoped=memory_module('scoped_readonly',payloads['remaining-backup-and-actor-readonly.py'])
    deploy=h.load('pinned_marketing',h.DEPLOY,h.DEPLOY_PIN)
    h.BOOTSTRAP_COMPONENTS=(base,scoped,deploy)
    h.BOOTSTRAP_SCANNER=memory_module('exact_scanner',payloads['recover-release-reviewed.py'])
    h.BOOTSTRAP_SOURCE=payloads['reboot-reviewed.py']
    prep=memory_module('new_attempt_preparation',payloads['preparation-readonly.py'])
    print(json.dumps(prep.collect(h),indent=2,sort_keys=True))
