    reason=str(error) if re.fullmatch("[A-Z0-9_]{1,160}",str(error)) else type(error).__name__
    print(json.dumps({"result":"STOP","CHECK_ID":'LOAD_00_NEW_ATTEMPT_READONLY',"reason":reason,"automaticRetry":False}))
